<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\Banner;
use App\Services\MediaService;
use Illuminate\Http\Request;
class BannerController extends Controller {public function __construct(private MediaService $media){}public function index(){return view('admin.banners.index',['banners'=>Banner::orderBy('placement')->orderBy('sort_order')->paginate(30)]);}public function create(){return view('admin.banners.form',['banner'=>new Banner]);}public function store(Request $r){$b=$this->save(new Banner,$r);return redirect()->route('admin.banners.edit',$b)->with('success','Banner created.');}public function edit(Banner $banner){return view('admin.banners.form',compact('banner'));}public function update(Request $r,Banner $banner){$this->save($banner,$r);return back()->with('success','Banner updated.');}public function destroy(Banner $banner){$this->media->delete($banner->image);$this->media->delete($banner->mobile_image);$banner->delete();return back()->with('success','Banner deleted.');}private function save(Banner $b,Request $r){$d=$r->validate(['placement'=>'required|in:home_hero,home_promo,category','eyebrow'=>'nullable|max:100','title'=>'required|max:191','subtitle'=>'nullable|max:191','description'=>'nullable|max:500','image'=>[$b->exists?'nullable':'required','image','max:6144'],'mobile_image'=>'nullable|image|max:6144','button_text'=>'nullable|max:60','button_url'=>'nullable|max:255','sort_order'=>'required|integer|min:0','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after:starts_at']);foreach(['image','mobile_image'] as $f)if($r->hasFile($f)){$this->media->delete($b->{$f});$d[$f]=$this->media->store($r->file($f),'banners');}$d['is_active']=$r->boolean('is_active');$b->fill($d)->save();return $b;}}
